import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../auth/AuthContext';

export default function Navbar() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  return (
    <nav style={{
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      padding: '14px 40px',
      background: '#0F172A', // ปรับเป็น midnight navy สุดเท่
      boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
      position: 'sticky',
      top: 0,
      zIndex: 100
    }}>
      {/* Brand Logo */}
      <div style={{ fontSize: '22px', fontWeight: '900', letterSpacing: '-0.5px' }}>
        <Link to="/" style={{ color: '#FFFFFF', textDecoration: 'none', display: 'flex', alignItems: 'center', gap: '8px' }}>
          <span>📍</span>
          <span>khong<span style={{ color: '#38BDF8' }}>unai</span></span>
        </Link>
      </div>

      {/* Nav Links */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '20px' }}>
        <Link to="/" style={{ color: '#F8FAFC', textDecoration: 'none', fontWeight: '500', fontSize: '14px' }}>
          หน้าแรก
        </Link>
        <Link to="/equipments" style={{ color: '#CBD5E1', textDecoration: 'none', fontWeight: '500', fontSize: '14px' }}>
          อุปกรณ์ทั้งหมด
        </Link>

        {user && user.role === 'member' && (
          <Link to="/my-borrowings" style={{ color: '#CBD5E1', textDecoration: 'none', fontWeight: '500', fontSize: '14px' }}>
            ประวัติการยืม
          </Link>
        )}

        {user && user.role === 'admin' && (
          <Link to="/admin" style={{ 
            color: '#FDE047', 
            background: 'rgba(255, 255, 255, 0.08)',
            padding: '6px 12px',
            borderRadius: '6px',
            textDecoration: 'none', 
            fontWeight: '600', 
            fontSize: '13px' 
          }}>
            🛡️ หลังบ้าน Admin
          </Link>
        )}

        {(!user || user.role === 'guest') ? (
          <div style={{ display: 'flex', gap: '10px', alignItems: 'center' }}>
            <Link to="/login" style={{
              color: '#FFFFFF',
              padding: '7px 14px',
              borderRadius: '8px',
              textDecoration: 'none',
              fontWeight: '600',
              fontSize: '13px',
              border: '1px solid rgba(255, 255, 255, 0.2)'
            }}>
              เข้าสู่ระบบ
            </Link>
            <Link to="/register" style={{
              background: '#0284C7',
              color: '#FFFFFF',
              padding: '7px 14px',
              borderRadius: '8px',
              textDecoration: 'none',
              fontWeight: '600',
              fontSize: '13px'
            }}>
              สมัครสมาชิก
            </Link>
          </div>
        ) : (
          <div style={{ display: 'flex', alignItems: 'center', gap: '14px' }}>
            <span style={{ fontSize: '13px', color: '#E2E8F0' }}>
              👤 {user.name || user.username} (<strong style={{ color: '#38BDF8' }}>{user.role}</strong>)
            </span>
            <button 
              onClick={() => { logout(); navigate('/'); }}
              style={{
                background: '#EF4444',
                color: '#FFFFFF',
                border: 'none',
                padding: '6px 12px',
                borderRadius: '6px',
                cursor: 'pointer',
                fontWeight: '600',
                fontSize: '12px'
              }}
            >
              ออกจากระบบ
            </button>
          </div>
        )}
      </div>
    </nav>
  );
}
